answer = []
for source in sources:
    number = source['number']
    info = metadata[number]
    row = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    row.update(
        proposed_xml=Path('drafts', info['file']).read_text().strip(),
        reason=info['reason'],
        review_notes=info['review_notes'],
        status='rewrite_draft',
    )
    if 'removed_provisions' in info:
        row.update(change_type='normative_reduction',
                   reform_policy_id='editorial_direction_2026_10_19',
                   removed_provisions=info['removed_provisions'])
    if source.get('benefit_check_required'):
        row['benefit_review'] = info['benefit_review']
    key = source['code_id'] + '|' + source['source_id']
    required = references['requirements'][key]
    if required:
        assert set(assessments[number]) == set(required)
        row['reference_checks'] = [
            {'target_key': target,
             'view_sha256': references['targets'][target]['view_sha256'],
             'assessment': assessments[number][target]}
            for target in required
        ]
    answer.append(row)

Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answer)} articles, {sum(len(a["proposed_xml"]) for a in answer)} caractères normatifs')
